#include<bits/stdc++.h>
#define lc (id * 2)
#define rc (id * 2 + 1)
#define md ((s + e) / 2)
#define dm ((s + e) / 2 + 1)
#define ln (e - s + 1)
using namespace std;

typedef long long ll;
const ll MXN = 3e5 + 10;
const ll MXS = MXN * 4;
ll n, timer, ans, Ans;
ll lazy[MXS], seg[MXS];
ll Stm[MXN], Ftm[MXN];
vector<ll> adj[MXN][2];
void Build(ll id = 1, ll s = 1, ll e = n){
    lazy[id] = -1, seg[id] = 0;
    if(ln > 1) Build(lc, s, md), Build(rc, dm, e);
}
void Shift(ll id, ll s, ll e){
    if(lazy[id] == -1) return;
    seg[id] = lazy[id];
    if(ln > 1) lazy[lc] = lazy[rc] = lazy[id];
    lazy[id] = -1;
}
void Upd(ll l, ll r, ll x, ll id = 1, ll s = 1, ll e = n){
    Shift(id, s, e);
    if(e < l || s > r) return;
    if(l <= s && e <= r){
        lazy[id] = x; Shift(id, s, e);
        return;
    }
    Upd(l, r, x, lc, s, md), Upd(l, r, x, rc, dm, e);
    seg[id] = max(seg[lc], seg[rc]);
}
ll Get(ll l, ll r, ll id = 1, ll s = 1, ll e = n){
    Shift(id, s, e);
    if(e < l || s > r) return 0;
    if(l <= s && e <= r) return seg[id];
    return max(Get(l, r, lc, s, md), Get(l, r, rc, dm, e));
}
void prep(ll u, ll par, ll f){
    Stm[u] = ++ timer;
    for(auto v : adj[u][f]){
        if(v != par) prep(v, u, f);
    }
    Ftm[u] = timer;
}
bool Is_Jad(ll j, ll u){
    return (Stm[j] <= Stm[u] && Ftm[u] <= Ftm[j]);
}
void DFS(ll u, ll par, ll f){
    ll j = Get(Stm[u], Ftm[u]);
    if(!j) Upd(Stm[u], Ftm[u], u), ans ++;
    else{
        if(Is_Jad(j, u)){
            Upd(Stm[j], Ftm[j], 0);
            Upd(Stm[u], Ftm[u], u);
        }
    }
    Ans = max(Ans, ans);
    for(auto v : adj[u][f]){
        if(v != par) DFS(v, u, f);
    }
    if(!j) Upd(Stm[u], Ftm[u], 0), ans --;
    else{
        if(Is_Jad(j, u)){
            Upd(Stm[u], Ftm[u], 0);
            Upd(Stm[j], Ftm[j], j);
        }
    }
}
void solve(){
    cin >> n, timer = ans = Ans = 0;
    for(int i = 1; i <= n; i ++) adj[i][0].clear(), adj[i][1].clear();
    for(int t = 0; t < 2; t ++) for(int u = 2, v; u <= n; u ++){
        cin >> v, adj[v][t].push_back(u), adj[u][t].push_back(v);
    }
    Build(), prep(1, 0, 1);
    DFS(1, 0, 0);
    cout << Ans << '\n';
}
int main(){
    ios::sync_with_stdio(0);cin.tie(0); cout.tie(0);
    ll q; cin >> q;
    while(q --) solve();
    return 0;
}
