				go[v] = v;
			else
				go[v] = go[(v + 1) % n];
		}
		for (auto [u, w] : g[v]) {
			int nex = go[(u + dp[v]) % n];
			dp[nex] = min(dp[nex], dp[v] + w + dis((u + dp[v]) % n, nex));
		}
	}
}

